"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { RelativeTime, type DateLike } from "./relative-time";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BARS: a status page that reads at a glance
 *
 *   overall   one line says how things are; it morphs when a
 *             service changes ("All systems operational" →
 *             "Some systems degraded") and its dot changes
 *             colour with it
 *   days      ninety days a service, a bar a day, drawn up
 *             from the baseline left to right; thirty on a
 *             narrow card
 *   read      point at a day (or arrow along with the keys) and
 *             one card glides from bar to bar above them, saying
 *             what happened that day
 *   incidents an open incident shows its updates newest first;
 *             a new update opens in on top and the status pill
 *             morphs (Investigating → Identified → Monitoring →
 *             Resolved). Past incidents fold behind a toggle
 *
 * Everything is props: feed it from your own checks or from
 * Better Stack, Instatus or Atlassian Statuspage.
 * ───────────────────────────────────────────────────────── */

export type { DateLike };
export type ServiceStatus =
  "operational" | "degraded" | "major" | "maintenance";
export type DayStatus =
  "operational" | "degraded" | "major" | "maintenance" | "none";

export interface StatusDay {
  /** "2026-10-14". */
  date: string;
  status: DayStatus;
  /** Minutes the service was degraded or down that day. */
  minutes?: number;
  /** Incident titles that touched this day. */
  incidents?: string[];
}

export interface StatusService {
  id: string;
  name: string;
  status: ServiceStatus;
  /** Uptime over the days shown, as a percentage. */
  uptime?: number;
  /** Oldest first; the last is today. */
  days: StatusDay[];
}

export type IncidentStage =
  "investigating" | "identified" | "monitoring" | "resolved";

export interface StatusIncident {
  id: string;
  title: string;
  impact: "minor" | "major" | "maintenance";
  stage: IncidentStage;
  /** Newest first. */
  updates: {
    id: string;
    at: DateLike;
    stage: IncidentStage;
    message: string;
  }[];
  /** Names of affected services. */
  services?: string[];
}

export interface StatusBarsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  services: StatusService[];
  incidents?: StatusIncident[];
  updatedAt?: DateLike;
  title?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BAR: Record<DayStatus, string> = {
  operational: "bg-emerald-500/80",
  degraded: "bg-amber-500",
  major: "bg-red-500",
  maintenance: "bg-foreground/35",
  none: "bg-muted shadow-[inset_0_0_0_1px_var(--border)]",
};
const WORD: Record<ServiceStatus, string> = {
  operational: "Operational",
  degraded: "Degraded",
  major: "Outage",
  maintenance: "Maintenance",
};
const WORD_TONE: Record<ServiceStatus, string> = {
  operational: "text-emerald-600 dark:text-emerald-400",
  degraded: "text-amber-700 dark:text-amber-400",
  major: "text-red-600 dark:text-red-400",
  maintenance: "text-muted-foreground",
};
const STAGES: Record<IncidentStage, string> = {
  investigating: "Investigating",
  identified: "Identified",
  monitoring: "Monitoring",
  resolved: "Resolved",
};
const NONE: StatusIncident[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];
const dayLabel = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  const t = new Date(y, m - 1, d);
  return `${DAYS[t.getDay()]} ${d} ${MONTHS[m - 1]}`;
};
const span = (min: number) =>
  min < 60
    ? `${min} min`
    : `${Math.floor(min / 60)} h${min % 60 ? ` ${min % 60} min` : ""}`;
const said = (d: StatusDay) =>
  d.status === "none"
    ? "No data"
    : d.status === "operational"
      ? "No incidents"
      : d.status === "maintenance"
        ? `Maintenance${d.minutes ? ` for ${span(d.minutes)}` : ""}`
        : `${d.status === "major" ? "Down" : "Degraded"}${d.minutes ? ` for ${span(d.minutes)}` : ""}`;

function overall(services: StatusService[]) {
  if (services.some((s) => s.status === "major"))
    return { text: "Major outage", tone: "major" as const };
  if (services.some((s) => s.status === "degraded"))
    return { text: "Some systems degraded", tone: "degraded" as const };
  if (services.some((s) => s.status === "maintenance"))
    return { text: "Maintenance in progress", tone: "maintenance" as const };
  return { text: "All systems operational", tone: "operational" as const };
}

/** A sentence that changes by lifting the old one out and the new one in. */
function Line({
  text,
  className = "",
  reduced,
}: {
  text: string;
  className?: string;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(text);
  const [old, setOld] = React.useState<{ k: number; t: string }[]>([]);
  const key = React.useRef(0);
  const ref = React.useRef<HTMLSpanElement>(null);
  if (text !== shown) {
    if (!reduced) setOld((o) => [...o, { k: ++key.current, t: shown }]);
    setShown(text);
  }
  React.useLayoutEffect(() => {
    if (!reduced && old.length)
      ref.current?.animate(
        [
          { opacity: 0, transform: "translateY(0.3em)", filter: "blur(4px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 420, delay: 80, easing: EASE, fill: "backwards" },
      );
  }, [shown]);
  return (
    <span className={`relative inline-block ${className}`}>
      <span ref={ref} className="inline-block">
        {shown}
      </span>
      {old.map((o) => (
        <Gone
          key={o.k}
          text={o.t}
          onDone={() => setOld((all) => all.filter((x) => x.k !== o.k))}
        />
      ))}
    </span>
  );
}

function Gone({ text, onDone }: { text: string; onDone: () => void }) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const a = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-0.3em)", filter: "blur(4px)" },
      ],
      { duration: 220, easing: EASE, fill: "forwards" },
    );
    if (a) a.onfinish = onDone;
    return () => a?.cancel();
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute top-0 left-0 whitespace-nowrap"
    >
      {text}
    </span>
  );
}

function Service({ s, reduced }: { s: StatusService; reduced: boolean }) {
  const id = React.useId();
  const barsRef = React.useRef<HTMLDivElement>(null);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const [active, setActive] = React.useState<number | null>(null);
  const [place, setPlace] = React.useState({ x: 0, ready: false });
  const [keyed, setKeyed] = React.useState(false);
  const [spoken, setSpoken] = React.useState("");
  const last = s.days.length - 1;

  // The bars draw up from the baseline, left to right, once.
  React.useLayoutEffect(() => {
    if (reduced) return;
    barsRef.current
      ?.querySelectorAll<HTMLElement>("[data-bar]")
      .forEach((b, i) =>
        b.animate([{ transform: "scaleY(0)" }, { transform: "none" }], {
          duration: 520,
          delay: 60 + i * 5,
          easing: EASE,
          fill: "backwards",
        }),
      );
  }, []);

  // The card glides to sit over the day, kept inside the row.
  React.useLayoutEffect(() => {
    if (active === null) return;
    const bars = barsRef.current;
    const card = cardRef.current;
    const bar = bars?.querySelector<HTMLElement>(`[data-bar="${active}"]`);
    if (!bars || !card || !bar) return;
    const center = bar.offsetLeft + bar.offsetWidth / 2;
    const x = Math.max(
      0,
      Math.min(
        bars.offsetWidth - card.offsetWidth,
        center - card.offsetWidth / 2,
      ),
    );
    setPlace((p) => (p.x === x && p.ready ? p : { x, ready: true }));
  }, [active]);

  const day = active === null ? null : s.days[active];
  const move = (to: number) => {
    const visible = [
      ...(barsRef.current?.querySelectorAll<HTMLElement>("[data-bar]") ?? []),
    ]
      .filter((b) => b.offsetParent !== null)
      .map((b) => Number(b.dataset.bar));
    const first = visible[0] ?? 0;
    const i = Math.max(first, Math.min(last, to));
    setActive(i);
    setKeyed(true);
    const d = s.days[i];
    setSpoken(
      `${dayLabel(d.date)}: ${said(d)}${d.incidents?.length ? `. ${d.incidents.join(". ")}` : ""}`,
    );
  };

  return (
    <div className="py-4 first:pt-0 last:pb-0">
      <div className="flex items-baseline justify-between gap-3">
        <p className="flex min-w-0 items-baseline gap-2">
          <span
            id={`${id}-name`}
            className="truncate text-[13.5px] font-medium tracking-[-0.01em]"
          >
            {s.name}
          </span>
          <span
            className={`shrink-0 text-[11.5px] transition-colors duration-500 ${WORD_TONE[s.status]}`}
          >
            <TextMorph>{WORD[s.status]}</TextMorph>
          </span>
        </p>
        {s.uptime !== undefined && (
          <p className="shrink-0 text-[11.5px] text-muted-foreground tabular-nums">
            <NumberRoll
              value={s.uptime / 100}
              format={{
                style: "percent",
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
              }}
            />{" "}
            uptime
          </p>
        )}
      </div>

      <div className="relative mt-2">
        {/* One card for every day: it glides between bars instead of a tooltip per bar. */}
        <div
          ref={cardRef}
          aria-hidden="true"
          className="pointer-events-none absolute bottom-full left-0 z-10 mb-2 w-[13.5rem] rounded-[12px] bg-popover px-3 py-2 text-popover-foreground shadow-[inset_0_0_0_1px_var(--border)]"
          style={{
            transform: `translateX(${place.x}px) translateY(${day ? 0 : 4}px)`,
            opacity: day ? 1 : 0,
            transition: reduced
              ? "none"
              : `transform ${place.ready && day ? 320 : 0}ms ${EASE}, opacity 180ms ${EASE}`,
          }}
        >
          {day && (
            <>
              <p className="text-[11.5px] text-muted-foreground">
                {dayLabel(day.date)}
              </p>
              <p
                className={`mt-0.5 text-[12.5px] font-medium ${day.status === "major" ? "text-red-600 dark:text-red-400" : day.status === "degraded" ? "text-amber-700 dark:text-amber-400" : ""}`}
              >
                {said(day)}
              </p>
              {day.incidents?.map((t) => (
                <p
                  key={t}
                  className="mt-1 text-[11.5px] leading-[1.4] text-muted-foreground"
                >
                  {t}
                </p>
              ))}
            </>
          )}
        </div>

        <div
          ref={barsRef}
          role="group"
          tabIndex={0}
          aria-labelledby={`${id}-name`}
          aria-describedby={`${id}-help`}
          onPointerMove={(e) => {
            const bar = (e.target as HTMLElement).closest<HTMLElement>(
              "[data-bar]",
            );
            if (bar) {
              setKeyed(false);
              setActive(Number(bar.dataset.bar));
            }
          }}
          onPointerLeave={() => !keyed && setActive(null)}
          onBlur={() => setActive(null)}
          onKeyDown={(e) => {
            const at = active ?? last;
            if (e.key === "ArrowLeft") move(at - 1);
            else if (e.key === "ArrowRight") move(at + 1);
            else if (e.key === "Home") move(0);
            else if (e.key === "End") move(last);
            else if (e.key === "Escape") return setActive(null);
            else return;
            e.preventDefault();
          }}
          onFocus={() => active === null && move(last)}
          className={`flex h-8 items-stretch gap-[2px] rounded-[4px] ${FOCUS} focus-visible:ring-offset-2 focus-visible:ring-offset-background`}
        >
          {s.days.map((d, i) => (
            <span
              key={d.date}
              data-bar={i}
              className={`min-w-[2px] flex-1 origin-bottom rounded-[2px] transition-[background-color,opacity] duration-500 ${BAR[d.status]} ${i < s.days.length - 30 ? "hidden @lg:block" : ""}`}
              style={{ opacity: active === null || active === i ? 1 : 0.55 }}
            />
          ))}
        </div>
        <span id={`${id}-help`} className="sr-only">
          {`${s.name} is ${WORD[s.status].toLowerCase()}. Arrow keys read each day.`}
        </span>
        <span className="sr-only" role="status">
          {keyed ? spoken : ""}
        </span>
      </div>

      <div className="mt-1.5 flex justify-between text-[11px] text-muted-foreground">
        <span>
          <span className="@lg:hidden">
            {Math.min(30, s.days.length)} days ago
          </span>
          <span className="hidden @lg:inline">{s.days.length} days ago</span>
        </span>
        <span>Today</span>
      </div>
    </div>
  );
}

function Incident({
  inc,
  reduced,
  open,
  onToggle,
}: {
  inc: StatusIncident;
  reduced: boolean;
  open: boolean;
  onToggle?: () => void;
}) {
  const seen = React.useRef(new Set(inc.updates.map((u) => u.id)));
  const listRef = React.useRef<HTMLOListElement>(null);
  // A new update opens in on top.
  React.useLayoutEffect(() => {
    const fresh = inc.updates.filter((u) => !seen.current.has(u.id));
    fresh.forEach((u) => seen.current.add(u.id));
    if (reduced || !fresh.length) return;
    for (const u of fresh) {
      const el = listRef.current?.querySelector<HTMLElement>(
        `[data-update="${CSS.escape(u.id)}"]`,
      );
      el?.animate(
        [
          { opacity: 0, transform: "translateY(-6px)", filter: "blur(4px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 460, easing: EASE },
      );
    }
  }, [inc.updates, reduced]);
  const tick =
    inc.stage === "resolved"
      ? "bg-emerald-500"
      : inc.impact === "major"
        ? "bg-red-500"
        : inc.impact === "minor"
          ? "bg-amber-500"
          : "bg-foreground/35";
  const updates = open ? inc.updates : inc.updates.slice(0, 1);
  return (
    <article className="relative rounded-[14px] py-3 pr-3 pl-4 shadow-[inset_0_0_0_1px_var(--border)]">
      <span
        aria-hidden="true"
        className={`absolute top-3 bottom-3 left-0 w-0.5 rounded-full transition-colors duration-500 ${tick}`}
      />
      <div className="flex items-start justify-between gap-3">
        <h3 className="min-w-0 text-[13.5px] font-medium tracking-[-0.01em]">
          {inc.title}
        </h3>
        <span
          className={`shrink-0 rounded-full px-2 py-0.5 text-[11px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-500 ${inc.stage === "resolved" ? "text-emerald-600 dark:text-emerald-400" : "text-foreground"}`}
        >
          <TextMorph>{STAGES[inc.stage]}</TextMorph>
        </span>
      </div>
      {inc.services?.length ? (
        <p className="mt-0.5 text-[11.5px] text-muted-foreground">
          {inc.services.join(", ")}
        </p>
      ) : null}
      <ol ref={listRef} className="mt-2.5 space-y-2.5">
        {updates.map((u) => (
          <li
            key={u.id}
            data-update={u.id}
            className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-x-3 text-[12.5px]"
          >
            <span className="text-[11.5px] text-muted-foreground">
              <span className="block font-medium text-foreground">
                {STAGES[u.stage]}
              </span>
              <RelativeTime date={u.at} />
            </span>
            <p className="leading-[1.5] text-foreground/90">{u.message}</p>
          </li>
        ))}
      </ol>
      {onToggle && inc.updates.length > 1 && (
        <button
          type="button"
          aria-expanded={open}
          onClick={onToggle}
          className={`mt-2 -ml-2 h-7 cursor-pointer rounded-full px-2 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
        >
          <TextMorph>
            {open ? "Fewer updates" : `All ${inc.updates.length} updates`}
          </TextMorph>
        </button>
      )}
    </article>
  );
}

export function StatusBars({
  services,
  incidents = NONE,
  updatedAt,
  title = "Status",
  className = "",
  ...props
}: StatusBarsProps) {
  const reduced = useReducedMotion();
  const [showPast, setShowPast] = React.useState(false);
  const [openPast, setOpenPast] = React.useState<string | null>(null);
  const now = overall(services);
  const active = incidents.filter((i) => i.stage !== "resolved");
  const past = incidents.filter((i) => i.stage === "resolved");
  const dot = {
    operational: "bg-emerald-500",
    degraded: "bg-amber-500",
    major: "bg-red-500",
    maintenance: "bg-foreground/40",
  }[now.tone];

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 border-b border-border px-4 py-4 @md:px-5">
        <h2 className="flex items-center gap-2.5 text-[17px] font-medium tracking-[-0.02em] @md:text-[19px]">
          <span
            className="relative grid size-2.5 place-items-center"
            aria-hidden="true"
          >
            <span
              className={`size-2.5 rounded-full transition-colors duration-500 ${dot}`}
            />
            {now.tone !== "operational" && !reduced && (
              <span
                className={`absolute inset-0 rounded-full opacity-40 animate-[ui-ping_1.8s_ease-out_infinite] ${dot}`}
              />
            )}
          </span>
          <span className="sr-only">{title}: </span>
          <Line text={now.text} reduced={reduced} />
        </h2>
        {updatedAt !== undefined && (
          <p className="text-[11.5px] text-muted-foreground">
            <RelativeTime date={updatedAt} prefix="Updated" />
          </p>
        )}
      </div>

      {active.length > 0 && (
        <section
          aria-label="Open incidents"
          className="space-y-2.5 border-b border-border px-4 py-4 @md:px-5"
        >
          {active.map((inc) => (
            <Incident key={inc.id} inc={inc} reduced={reduced} open />
          ))}
        </section>
      )}

      <section
        aria-label="Services"
        className="divide-y divide-border px-4 py-4 @md:px-5"
      >
        {services.map((s) => (
          <Service key={s.id} s={s} reduced={reduced} />
        ))}
      </section>

      {past.length > 0 && (
        <section
          aria-label="Past incidents"
          className="border-t border-border px-4 py-3 @md:px-5"
        >
          <button
            type="button"
            aria-expanded={showPast}
            onClick={() => setShowPast((v) => !v)}
            className={`-ml-2 inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-full px-2 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <TextMorph>
              {showPast ? "Hide past incidents" : "Past incidents"}
            </TextMorph>
            <span className="tabular-nums">
              <NumberRoll value={past.length} />
            </span>
          </button>
          <div
            className="grid"
            inert={!showPast}
            style={{
              gridTemplateRows: showPast ? "1fr" : "0fr",
              opacity: showPast ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE}, opacity 300ms ${EASE}`,
            }}
          >
            <div className="min-h-0 min-w-0 overflow-clip">
              <div className="space-y-2.5 pt-2.5 pb-1">
                {past.map((inc) => (
                  <Incident
                    key={inc.id}
                    inc={inc}
                    reduced={reduced}
                    open={openPast === inc.id}
                    onToggle={() =>
                      setOpenPast((o) => (o === inc.id ? null : inc.id))
                    }
                  />
                ))}
              </div>
            </div>
          </div>
        </section>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * RELATIVE TIME: "2 min ago" that keeps itself true
 *
 *   tick      it re-renders only when the words would change:
 *             on the next minute under an hour, the next hour
 *             under a day; nothing runs between
 *   roll      the number rolls up ("2 min" → "3 min") and the
 *             unit morphs when it changes ("59 min" → "1 h")
 *   date      past a week it settles on the date ("12 Sep")
 *
 * Until it's mounted it renders the date, so the server and the
 * first paint agree; the hover title is always the full time.
 * ───────────────────────────────────────────────────────── */

export type DateLike = Date | string | number;

export interface RelativeTimeProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children"
> {
  date: DateLike;
  /** Said before the time, e.g. "Last used". */
  prefix?: string;
  /** Under a minute. */
  justNow?: string;
  locales?: string | string[];
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export const toTime = (d: DateLike) =>
  d instanceof Date
    ? d.getTime()
    : typeof d === "number"
      ? d
      : new Date(d).getTime();

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** "12 Sep", with the year when it isn't this one; pass locales to use the browser's own format. */
export function formatDate(d: DateLike, locales?: string | string[]) {
  const t = new Date(toTime(d));
  const sameYear = t.getFullYear() === new Date().getFullYear();
  if (locales)
    return t.toLocaleDateString(
      locales,
      sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    );
  return `${t.getDate()} ${MONTHS[t.getMonth()]}${sameYear ? "" : ` ${t.getFullYear()}`}`;
}

type Parts = { n: number | null; unit: string; next: number };

function parts(
  at: number,
  now: number,
  justNow: string,
  locales?: string | string[],
): Parts {
  const ago = Math.max(0, now - at);
  if (ago < MINUTE) return { n: null, unit: justNow, next: MINUTE - ago };
  if (ago < HOUR)
    return {
      n: Math.floor(ago / MINUTE),
      unit: "min ago",
      next: MINUTE - (ago % MINUTE),
    };
  if (ago < DAY) {
    const h = Math.floor(ago / HOUR);
    return {
      n: h,
      unit: h === 1 ? "hour ago" : "hours ago",
      next: HOUR - (ago % HOUR),
    };
  }
  if (ago < 7 * DAY) {
    const d = Math.floor(ago / DAY);
    return {
      n: d,
      unit: d === 1 ? "day ago" : "days ago",
      next: DAY - (ago % DAY),
    };
  }
  return { n: null, unit: formatDate(at, locales), next: 0 };
}

const subscribeMounted = () => () => {};

export function RelativeTime({
  date,
  prefix,
  justNow = "just now",
  locales,
  className = "",
  ...props
}: RelativeTimeProps) {
  const at = toTime(date);
  const mounted = React.useSyncExternalStore(
    subscribeMounted,
    () => true,
    () => false,
  );
  const [now, setNow] = React.useState(() => Date.now());
  const p = parts(at, mounted ? now : at + 8 * DAY, justNow, locales);

  // One timer, set for the moment the words change.
  React.useEffect(() => {
    if (!mounted || !p.next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), p.next + 50);
    return () => window.clearTimeout(timer);
  }, [mounted, p.next, now]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [at]);

  const iso = new Date(at).toISOString();
  return (
    <time
      dateTime={iso}
      title={new Date(at).toLocaleString(locales ?? "en-GB", {
        dateStyle: "medium",
        timeStyle: "short",
      })}
      className={`inline-flex items-baseline whitespace-nowrap tabular-nums ${className}`}
      {...props}
    >
      {prefix && <span>{prefix}&nbsp;</span>}
      {/* Remounted once on the client, so the first real words appear without a morph. */}
      <Words key={mounted ? "client" : "server"} n={p.n} unit={p.unit} />
    </time>
  );
}

function Words({ n, unit }: { n: number | null; unit: string }) {
  return (
    <>
      <span
        aria-hidden={n === null || undefined}
        className="inline-grid transition-[grid-template-columns] duration-[380ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
        style={{ gridTemplateColumns: n === null ? "0fr" : "1fr" }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pr-[0.25em]">
            <NumberRoll value={n ?? 1} direction="up" />
          </span>
        </span>
      </span>
      <TextMorph>{unit}</TextMorph>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

